  "offsite.prune.title": "5 · Čiščenje zunanje kopije",
  "offsite.prune.info": "Ta korak samo poroča, kaj se dogaja, ničesar ne nastavlja. Ali se ta kopija čisti, določata samo-dodajanje iz koraka 4 in vrednosti hrambe v Nastavitve, Hramba. Če želiš kopijo s samo-dodajanjem vseeno počistiti, zaženi restic forget --prune na strani shrambe, bodisi po lastnem urniku bodisi tako, da za kratko postaviš drugi strežnik REST brez samo-dodajanja, počistiš prek njega in ga spet ugasneš.",
  "offsite.prune.stateFarSide": "Od tu te kopije ne čisti nič. Samo-dodajanje je vklopljeno, zato BombVault vanjo samo dodaja, čiščenje pa je naloga strani shrambe.",
