  "coverage.hint": "Vse na tem strežniku, česar ne zajame nobena samodejna varnostna kopija. Kartica zaščite zgoraj pove, ali so se načrtovane varnostne kopije izvedle pravočasno; ta kartica pokaže, kaj sploh ni na urniku, tega pa ne pokaže nobena druga stran. Vrsta varnostnega kopiranja, ki si jo izklopil, se tukaj ne šteje. Tudi nabori podatkov ZFS, ki jih nisi dodal, se tukaj ne štejejo; stran ZFS jih našteje.",
