  "dbdump.toggle": "Izvoz podatkovne baze pred vsako varnostno kopijo",
  "dbdump.toggleHint": "BombVault je ta vsebnik prepoznal kot podatkovno bazo {engine}. Pred vsako varnostno kopijo od delujočega strežnika zahteva celoten izvoz SQL in ga shrani kot samostojno obnovitveno točko, naravnost v skladišče kopij, ne da bi na tvoje diske zapisal datoteko. Obnovitev uporabi kopijo datotek, narejeno po zaustavitvi vsebnika; izvoz je druga kopija, ki jo lahko preneseš ali uvoziš. Neuspel izvoz nikoli ne podre varnostne kopije, prikaže se kot samostojen neuspel zagon.",
  "dbdump.toggleHintLabel": "Oznaka vsebnika bombvault.dbdump vklopi izvoz za to podatkovno bazo {engine}. Pred vsako varnostno kopijo BombVault od delujočega strežnika zahteva celoten izvoz SQL in ga shrani kot samostojno obnovitveno točko. Neuspel izvoz nikoli ne podre varnostne kopije, prikaže se kot samostojen neuspel zagon.",
  "dbdump.toggleHintOnlyCopy": "Pred vsako varnostno kopijo BombVault od tega delujočega strežnika {engine} zahteva celoten izvoz SQL in ga shrani kot samostojno obnovitveno točko. Pri tem vsebniku je izvoz edina skladna kopija baze: njena podatkovna mapa se bodisi kopira med delovanjem strežnika bodisi je ni v nobeni kopiji. Pusti izvoz vklopljen. Neuspel izvoz nikoli ne podre varnostne kopije, prikaže se kot samostojen neuspel zagon.",
  "dbdump.toggleHintUnknown": "Pred vsako varnostno kopijo BombVault od tega delujočega strežnika {engine} zahteva celoten izvoz SQL in ga shrani kot samostojno obnovitveno točko. Kje ta vsebnik hrani svojo podatkovno mapo, ni bilo mogoče ugotoviti, zato ni znano, ali kopija datotek vsebuje kaj uporabnega. Izvoz je kopija, na katero se lahko zaneseš. Pusti ga vklopljenega. Neuspel izvoz nikoli ne podre varnostne kopije, prikaže se kot samostojen neuspel zagon.",
  "dbdump.lookalikeHint": "Ta vsebnik je videti kot podatkovna baza {engine}, a BombVault njegove slike ne pozna zanesljivo. Vklopi izvoz, če to je; če nato spodleti, se slika ne drži običajnih nastavitev in ga lahko spet izklopiš.",
