  "dbdump.labelOff": "Izklopljeno z oznako vsebnika bombvault.dbdump=false.",
  "dbdump.globalOff": "Samodejni izvozi podatkovnih baz so izklopljeni za vse vsebnike v Nastavitve, Splošno.",
  "dbdump.offConfirmLive": "Izklopim izvoz za to podatkovno bazo? Njena podatkovna mapa se kopira med delovanjem strežnika, zato brez izvoza ne obstaja nobena skladna kopija.",
  "dbdump.offConfirmNone": "Izklopim izvoz za to podatkovno bazo? Njene podatkovne mape ni v nobeni kopiji, zato se brez izvoza od nje ne ohrani nič.",
  "dbdump.offConfirmUnknown": "Izklopim izvoz za to podatkovno bazo? BombVault ni mogel ugotoviti, kje je njena podatkovna mapa, zato ni znano, ali katera koli kopija vsebuje kaj uporabnega.",
  "dbdump.coverageStopped": "Podatkovna mapa: shranjena med zaustavljenim vsebnikom.",
  "dbdump.coverageLive": "Podatkovna mapa: kopirana med delovanjem strežnika. Izvoz je skladna kopija.",
  "dbdump.coverageNone": "Podatkovna mapa: v nobeni kopiji. Izvoz je edina kopija.",
  "dbdump.coverageUnknown": "Podatkovna mapa: ni bilo mogoče ugotoviti. Pusti izvoz vklopljen.",
  "dbdump.coverageHint": "Podatkovna baza ves čas piše v svoje datoteke. Kopija teh datotek je zanesljiva le, kadar je strežnik med njenim nastajanjem zaustavljen, in prav to BombVault naredi za mape v kopiji vsebnika. Mape projekta compose ali nabora map se kopirajo med delovanjem strežnika, mape zunaj appdata pa se sploh ne kopirajo. V teh primerih je izvoz tisto, iz česar bi obnovil.",
