  "dbdump.updateWarn": "To je podatkovna baza. Posodobitev slike jo lahko prestavi na novo glavno različico, ki zavrne staro podatkovno mapo. Izvoz, narejen tik pred posodobitvijo, lahko nato uvoziš v novo različico iz plošče Kopije.",
  "dbdump.updateWarnSameMajor": "To je podatkovna baza. Posodobitev slike jo lahko prestavi na novo glavno različico. MySQL in MariaDB uvozita izvoz samo v glavno različico, iz katere izhaja, zato če nova različica zavrne staro podatkovno mapo, vrni sliko na prejšnjo različico in tam uvozi izvoz, narejen tik pred posodobitvijo.",
  "dbdump.stackRestoreWarn": "one=Podatki za {names} se kopirajo med delovanjem sklada. Po obnovitvi uvozi njegov najnovejši izvoz podatkovne baze, preden uporabiš aplikacijo.|two=Podatki za {names} se kopirajo med delovanjem sklada. Po obnovitvi uvozi njuna najnovejša izvoza podatkovne baze, preden uporabiš aplikaciji.|few=Podatki za {names} se kopirajo med delovanjem sklada. Po obnovitvi uvozi njihove najnovejše izvoze podatkovne baze, preden uporabiš aplikacije.|other=Podatki za {names} se kopirajo med delovanjem sklada. Po obnovitvi uvozi njihov najnovejši izvoz podatkovne baze, preden uporabiš aplikacije.",
  "dbdump.introNotice": "one=BombVault pred vsako kopijo izvozi podatkovne baze, ki jih prepozna, kot samostojne obnovitvene točke. Tu prepoznana: {n} podatkovna baza, {name}. To lahko izklopiš pri posameznem vsebniku na njegovi kartici ali za vse vsebnike v Nastavitvah.|two=BombVault pred vsako kopijo izvozi podatkovne baze, ki jih prepozna, kot samostojne obnovitvene točke. Tu prepoznani: {n} podatkovni bazi, prva je {name}. To lahko izklopiš pri posameznem vsebniku na njegovi kartici ali za vse vsebnike v Nastavitvah.|few=BombVault pred vsako kopijo izvozi podatkovne baze, ki jih prepozna, kot samostojne obnovitvene točke. Tu prepoznane: {n} podatkovne baze, prva je {name}. To lahko izklopiš pri posameznem vsebniku na njegovi kartici ali za vse vsebnike v Nastavitvah.|other=BombVault pred vsako kopijo izvozi podatkovne baze, ki jih prepozna, kot samostojne obnovitvene točke. Tu prepoznanih: {n} podatkovnih baz, prva je {name}. To lahko izklopiš pri posameznem vsebniku na njegovi kartici ali za vse vsebnike v Nastavitvah.",
  "dbdump.introDismiss": "Razumem",
  "dbdump.fixAuth": "Preveri spremenljivke z geslom na samem vsebniku podatkovne baze (na primer POSTGRES_PASSWORD, MARIADB_ROOT_PASSWORD ali MYSQL_ROOT_PASSWORD, oziroma njihove različice _FILE). Izvoz uporablja prav te.",
  "dbdump.fixPrivileges": "Izvoz se je lahko prijavil le kot uporabnik aplikacije, ki mu manjka potrebna pravica. Daj vsebniku pravo geslo za root namesto naključnega.",
  "dbdump.fixUnreachable": "Strežnik podatkovne baze ni odgovoril na svojem krajevnem vtiču. Poglej dnevnik vsebnika, morda se še zaganja ali pa se je sesul.",
  "dbdump.fixNotRunning": "Vsebnik je bil zaustavljen ali se je ponovno zaganjal, ko je tekla kopija. Če se ponovno zaganja ves čas, poglej njegov dnevnik.",
  "dbdump.fixNoClient": "Slika nima orodja za izvoz. Uporabi uradno sliko ali izklopi izvoz za ta vsebnik.",
  "dbdump.fixSecret": "Datoteke z geslom, navedene v spremenljivki _FILE, uporabnik vsebnika ni mogel prebrati. Preveri pot in njena dovoljenja.",
  "dbdump.fixNoCredentials": "Nastavitve vsebnika ne vsebujejo niti gesla za root niti uporabnika s podatkovno bazo. Nastavi MARIADB_ROOT_PASSWORD (ali MYSQL_ROOT_PASSWORD) oziroma uporabnika in bazo.",
  "dbdump.fixNeedsUpgrade": "Sistemske tabele baze so iz starejše različice. Dodaj vsebniku spremenljivko MARIADB_AUTO_UPGRADE z vrednostjo 1 in ga ponovno zaženi, ali pa enkrat zaženi mariadb-upgrade znotraj vsebnika.",
  "dbdump.fixTimeout": "Izvoz je dosegel svojo časovno omejitev. Za zelo veliko bazo dodaj vsebniku BombVault spremenljivko DB_DUMP_MAX_HOURS (Unraid: uredi vsebnik, Add another Path, Port, Variable), na primer 12.",
  "dbdump.fixBackupCap": "Celotna kopija je dosegla BACKUP_MAX_HOURS, medtem ko je tekel izvoz. Zvišaj BACKUP_MAX_HOURS na vsebniku BombVault.",
  "dbdump.fixStalled": "Izvoz je nehal napredovati, običajno zato, ker je aplikacija držala zaklep. Poskusi se znova z naslednjo kopijo.",
  "dbdump.fixDumpData": "Orodje za izvoz se je ustavilo s prikazanim sporočilom. Poskusi se znova z naslednjo kopijo; če še naprej spodleti, sporočilo imenuje vzrok.",
  "dbdump.fixDocker": "Docker ni zagnal ukaza za izvoz. Običajno je bil vsebnik zaustavljen, začasno ustavljen ali znova ustvarjen, medtem ko se je kopija zaganjala. Poskusi se znova z naslednjo kopijo; če se ponavlja, preveri storitev Docker in dostop BombVaulta do nje.",
  "dbdump.fixRepository": "Skladišče kopij izvoza ni sprejelo ali pa je shranilo manj bajtov, kot jih je bilo izvoženih. Preveri skladišče v Nastavitve, Shramba; izvoz se poskusi znova z naslednjo kopijo.",
  "dbdump.fixLeftover": "Poškodovanega izvoza ni bilo mogoče odstraniti iz skladišča. Izbriši ga s seznama izvozov v plošči Kopije.",
  "dbdump.fixHelper": "BombVaultov pomočnik za izvoz se je končal brez rezultata. Če se ponovi, odpri prijavo in priloži diagnostični paket.",
  "dbdump.listTitle": "Izvozi baze podatkov",
  "dbdump.listHint": "Vsak izvoz je popoln izvoz SQL, vzet iz delujoče baze podatkov tik pred njeno varnostno kopijo. BombVault izvoza nikoli ne naloži nazaj sam: obnovitev vsebnika vrne njegove datoteke, in če so bile shranjene ob ustavljenem vsebniku, so novejša kopija. Izvoz uporabi, kadar te datoteke ne zadoščajo: kopirane so bile med delovanjem strežnika ali pa sploh ne, baza je prešla na novo glavno različico ali pa je podatkovna mapa poškodovana. Uvoz postavi izvoz v sveže zagnano prazno bazo in staro podatkovno mapo pusti zraven. Popolna datoteka .sql se konča z vrstico komentarja \"complete\".",
  "dbdump.none": "Izvozov baze podatkov še ni.",
