  "dbdump.saveHint": "Zapiše izvoz kot datoteko v izbrano mapo na strežniku, z lastnikom nobody:users, da jo lahko odpreš prek omrežne mape v skupni rabi. Datoteka vsebuje vse tabele in zgoščene vrednosti gesel uporabnikov baze; hrani jo tam, kamor sežeš samo ti.",
  "dbdump.saveCancelHint": "Preklic ustavi shranjevanje in odstrani nedokončano datoteko.",
  "dbdump.savedTo": "Shranjeno v {path}",
  "dbdump.import": "Uvozi v svežo bazo podatkov",
  "dbdump.importConfirm": "Uvozim ta izvoz {engine} {version} v {container}? BombVault ustavi vsebnik, njegovo podatkovno mapo odmakne vstran (ostane shranjena, nič se ne izbriše), zažene vsebnik s prazno podatkovno mapo in uvozi izvoz. Programi, ki uporabljajo to bazo, bodo videli njeno stanje iz časa izvoza.",
  "dbdump.importConfirmNoVersion": "Uvozim ta izvoz {engine} v {container}? BombVault ustavi vsebnik, njegovo podatkovno mapo odmakne vstran (ostane shranjena, nič se ne izbriše), zažene vsebnik s prazno podatkovno mapo in uvozi izvoz. Programi, ki uporabljajo to bazo, bodo videli njeno stanje iz časa izvoza.",
  "dbdump.importNoVersion": "Ta izvoz ne zabeleži različice svoje baze podatkov. Uvoz spodleti, če ga strežnik ne zna prebrati.",
  "dbdump.importStops": "one=Med uvozom BombVault ustavi tudi {apps} in jo nato znova zažene. Če uvoz spodleti, potem ko se je že začel, stari podatki ostanejo na strani, aplikacija pa ustavljena.|two=Med uvozom BombVault ustavi tudi ti dve aplikaciji: {apps}. Nato ju znova zažene. Če uvoz spodleti, potem ko se je že začel, stari podatki ostanejo na strani, aplikaciji pa ustavljeni.|few=Med uvozom BombVault ustavi tudi te aplikacije: {apps}. Nato jih znova zažene. Če uvoz spodleti, potem ko se je že začel, stari podatki ostanejo na strani, aplikacije pa ustavljene.|other=Med uvozom BombVault ustavi tudi te aplikacije: {apps}. Nato jih znova zažene. Če uvoz spodleti, potem ko se je že začel, stari podatki ostanejo na strani, aplikacije pa ustavljene.",
  "dbdump.importDone": "Baza podatkov je uvožena.",
  "dbdump.importRefused.busy": "Trenutno teče druga varnostna kopija ali obnovitev. Poskusi znova, ko se konča.",
  "dbdump.importRefused.notRunning": "Najprej zaženi vsebnik; uvoz potrebuje delujoč strežnik.",
  "dbdump.importRefused.engineMismatch": "Ta izvoz prihaja iz druge vrste baze podatkov, kot jo poganja vsebnik.",
  "dbdump.importRefused.noDataMount": "BombVault ne doseže podatkovne mape tega vsebnika, zato je ne more varno odmakniti. Uvozi izvoz ročno, kot opisuje komplet za obnovitev.",
  "dbdump.importRefused.version": "Strežnik teče v različici {server}, izvoz prihaja iz {dump}. Za ta uvoz uporabi sliko z različico {dump} ali novejšo.",
  "dbdump.importRefused.versionSameMajor": "Strežnik teče v različici {server}, izvoz prihaja iz {dump}. MySQL in MariaDB uvozita izvoz samo v glavno različico, iz katere izhaja, zato za ta uvoz uporabi sliko z različico {dump}.",
  "dbdump.importRefused.damaged": "Ta izvoz je poškodovan in ga ni mogoče uvoziti.",
  "dbdump.importRefused.notADump": "Ta posnetek ni izvoz baze podatkov tega vsebnika.",
  "dbdump.restoreLiveWarn": "Datoteke te baze se kopirajo med delovanjem strežnika, zato se obnovljene datoteke morda ne bodo zagnale čisto. Če se ne, uvozi izvoz, vzet s to varnostno kopijo; naveden je spodaj.",
  "dbdump.restoreNoneWarn": "Podatkovne mape te baze v varnostni kopiji ni. Obnovitev vrne vsebnik s prazno bazo; nato uvozi izvoz s seznama spodaj.",
  "dbdump.deleteConfirm": "Izbrišem ta izvoz baze podatkov? Odstrani se iz shrambe (za sprostitev prostora zaženi Prune v nastavitvah). Tega ni mogoče razveljaviti.",
