  "flash.zipExport.keepHistory": "Ohrani izvožene zip datoteke",
  "flash.zipExport.keepHistoryHint": "Izklopljeno: ohrani eno datoteko flash-latest.zip, ki se vsakič prepiše. Vklopljeno: ohrani najnovejših N datotek flash-<datum>.zip z žigom časa. To je ločeno od resticove hrambe: izklopljeno ohrani eno, vedno prepisano datoteko (nikoli ne zapolni cilja); vklopljeno ohrani najnovejših N in izbriše starejše.",
  "flash.zipExport.keepN": "Zipov za ohranitev",
  "flash.zipExport.keepNHint": "Ohranjenih je najnovejših N zipov z žigom časa; starejši se izbrišejo samodejno.",
  "flash.zipExport.latestNote": "Ena datoteka flash-latest.zip se prepiše po vsaki varnostni kopiji.",
  "flash.zipExport.plaintextWarn": "Izvožen .zip ni šifriran, tudi če je tvoj repozitorij za Flash. Sinhroniziraj ga samo, kamor zaupaš.",
  "flash.zipExport.pathRequired": "Za vklop izberi izvozno mapo.",
  "export.encrypt.hint": "Restic repozitoriji so že šifrirani. To po želji zapečati še navadne izvozne artefakte (tar.gz vsebnikov in VM-jev ter njihove spremne xml datoteke, in zip Flasha) z age, tako da jih je varno shraniti ali premakniti izven naprave.",
  "export.encrypt.ageInfo": "age (age-encryption.org) je majhno, sodobno orodje za šifriranje datotek, enostavnejša alternativa GPG za zapečatenje datoteke enemu ali več prejemnikom.",
  "export.encrypt.enable": "Šifriraj izvoze z age",
  "export.encrypt.enableHint": "Ko je vklopljeno, so izvozi vsebnikov, VM-jev in Flasha pred zapisom na disk zapečateni z age in dobijo pripono .age.",
  "export.encrypt.kitSealed": "Tudi obnovitveni komplet je zapečaten in pride kot bombvault-recovery-kit.md.age. Ostane berljivo besedilo (ASCII armor), zato ga je še vedno mogoče prilepiti v upravitelja gesel ali natisniti, za odpiranje pa boš potreboval svoj zasebni ključ age: shrani ta ključ nekam, kjer ni odvisen od samega kompleta.",
  "export.encrypt.recipients": "Prejemniki age",
  "export.encrypt.recipientsHint": "En prejemnik na vrstico. Uporabi javni ključ age (age1...) ali javni ključ SSH. Za dešifriranje izven naprave je potreben ujemajoč zasebni ključ. S šifriranjem vklopljenim in brez veljavnega prejemnika izvoz spodleti, namesto da bi zapisal navadno besedilo.",
  "export.encrypt.recipientsPlaceholder": "age1qz...\nssh-ed25519 AAAA...",
  "export.encrypt.recipientsRequired": "Dodaj vsaj enega prejemnika age, sicer bo šifriran izvoz spodletel.",

