  // Guided Recovery tab
  "nav.recovery": "Obnova",
  "recovery.step1": "Ali lahko BombVault prebere tvoje varnostne kopije?",
  "recovery.appKeyExplain": "Za branje obstoječih varnostnih kopij ta vsebnik potrebuje ISTI APP_KEY, kot ga je uporabljal prej. Najdeš ga v svojem obnovitvenem kompletu. Nastavi ga v Unraidovi predlogi vsebnika, če še ni, nato znova preveri.",
  "recovery.appKeyRemedy": "Šifrirni ključ se ne ujema s temi varnostnimi kopijami. V predlogi vsebnika nastavi izvirni APP_KEY (iz svojega obnovitvenega kompleta), nato znova preveri.",
  "recovery.readable": "Tvoje varnostne kopije so berljive.",
  "recovery.readFrom": "Prebrano iz:",
  "recovery.notReachable": "Tvojih varnostnih kopij še ni bilo mogoče doseči. Spodaj priklopi lokacijo, nato znova preveri.",
  "recovery.recheck": "Preveri",
  "recovery.stepConfig": "Obnovi lastne nastavitve BombVaulta",
  "recovery.configHint": "Na obnovljenem strežniku najprej obnovi lastne nastavitve BombVaulta (njegove poti za varnostno kopiranje, zunanje cilje in poverilnice), tako da so spodnji koraki že vnaprej izpolnjeni. Usmeri ga na varnostno kopijo nastavitev, ki si jo nastavil prej. Nimaš varnostne kopije nastavitev? Preskoči to in spodaj ročno priklopi svoje varnostne kopije.",
  "recovery.configAppKeyReminder": "Tvoj APP_KEY se mora ujemati s to varnostno kopijo, to je preverjanje v zgornjem koraku 1.",
  "recovery.configSourceLabel": "Kje je varnostna kopija nastavitev?",
