  "recovery.configManualRestart": "Tvoje nastavitve so pripravljene. Znova zaženi vsebnik BombVault v Unraidu, nato nadaljuj, uveljavijo se ob naslednjem zagonu.",
  "recovery.configReloadWhenBack": "BombVault se vrača dlje, kot je pričakovano. Ko je spet dosegljiv, znova naloži to stran, da naložiš obnovljene nastavitve.",
