  "recovery.encAbsent": "Na teh mestih še ni nobenega repozitorija varnostnih kopij, zato ni česa zaznati, tvoja izbira spodaj odloči, kako bo ustvarjen.",
  "recovery.encUnknown": "Zaenkrat ni mogoče ugotoviti: repozitorijev ni bilo mogoče odpreti, zato je njihov način šifriranja neznan. Popravi lokacijo zgoraj in preveri znova ali ga nastavi sam, če ga že poznaš.",
  "recovery.encConflict": "Tvoji repozitoriji si nasprotujejo: nekateri so šifrirani, drugi ne. Ena nastavitev ne more odpreti obojih. Usmeri izstopajočega na novo, prazno lokacijo ali obnovi le iz ujemajočega se niza.",
  "recovery.encUnconfigured": "Lokacija za varnostne kopije še ni nastavljena. Spodaj vpiši poti in se nato poveži.",
  "recovery.encDetectHint": "Šifriranje ni stvar okusa: repozitorij nastane bodisi z geslom (izpeljanim iz tvojega APP_KEY) bodisi brez njega, in to se pozneje nikoli več ne spremeni. BombVault odpre nastavljene repozitorije, da vidi, kateri primer velja, tako da obnova na sveži napravi ne zahteva ugibanja. Nedosegljiv repozitorij se javi kot neznan, nikoli kot nešifriran.",
