  "mcp.title": "Strežnik MCP",
  "mcp.hint": "Pomočnikom z umetno inteligenco, kot je Claude, omogoča, da prek Model Context Protocol berejo stanje varnostnih kopij tega strežnika, zaganjajo kopiranja in prekinjajo tista, ki so jih sami zagnali. Obnovitve, brisanja in nastavitve ostanejo v tem spletnem vmesniku.",
  "mcp.statusOff": "Izklopljeno: ključa ni",
  "mcp.statusOn": "one=Vklopljeno, {n} aktiven ključ|two=Vklopljeno, {n} aktivna ključa|few=Vklopljeno, {n} aktivni ključi|other=Vklopljeno, {n} aktivnih ključev",
  "mcp.statusNoneWorks": "Izklopljeno: noben ključ ne deluje",
  "mcp.noPasswordWarning": "Geslo za prijavo ni nastavljeno, zato je ta spletni vmesnik odprt vsem v tvojem omrežju, in kdor ga lahko odpre, lahko tudi ustvari ključ.",
  "mcp.setPassword": "Nastavi geslo za prijavo",
  "mcp.needsPasswordForHost": "Ta stran je bila odprta kot {host}. Brez gesla za prijavo je ključe mogoče ustvarjati in zamenjati samo z naslova IP ali krajevnega imena, kot je tower ali tower.local, da nobena spletna stran z interneta ne more ustvariti ključa. Geslo za prijavo to omejitev za ta naslov odpravi. BombVault lahko odpreš tudi prek njegovega krajevnega naslova.",
  "mcp.restoreRevokedNotice": "Obnovitev nastavitev je preklicala vse ključe MCP. Ustvari nove ključe za svoje pomočnike.",
  "mcp.appKeyChanged": "APP_KEY se je od nastanka teh ključev spremenil, zato ti ne delujejo več. Zamenjaj vsak ključ in posodobi svoje pomočnike.",
  "mcp.keyUnusable": "Po spremembi APP_KEY ne velja več",
  "mcp.loadFailed": "Ključev MCP ni bilo mogoče naložiti",
  "mcp.endpointLabel": "Končna točka",
  "mcp.endpointHint": "Naslov, s katerim se poveže tvoj pomočnik. Govori Streamable HTTP in pričakuje ključ v glavi Authorization ali X-API-Key ali pa žeton za dostop, ko se je pomočnik prijavil prek OAuth.",
  "mcp.newKey": "Nov ključ",
  "mcp.labelLabel": "Ime ključa",
  "mcp.labelPlaceholder": "Claude Code na prenosniku",
  "mcp.allowStart": "Dovoli zagon kopiranj",
  "mcp.allowStartHint": "Ko je to vklopljeno, lahko pomočnik zažene kopiranje ene postavke, celotnega področja ali Backup Everything in prekine kopiranja, ki jih je sam zagnal: največ {n} na uro, z razmikom {minutes} minut za isto postavko in {perDay} na postavko dnevno. Kopiranje ustavi delujoče vsebnike, dokler se ne konča. Brez tega lahko ključ samo bere.",
  "mcp.createKey": "Ustvari ključ",
  "mcp.created": "Ključ ustvarjen",
  "mcp.labelInvalid": "Daj ključu ime z največ 64 znaki.",
  "mcp.labelTaken": "Aktiven ključ se že tako imenuje.",
  "mcp.limitReached": "one=Obstaja že {n} aktiven ključ. Prekliči ga, preden ustvariš novega.|two=Obstajata že {n} aktivna ključa. Enega prekliči, preden ustvariš novega.|few=Obstajajo že {n} aktivni ključi. Enega prekliči, preden ustvariš novega.|other=Obstaja že {n} aktivnih ključev. Enega prekliči, preden ustvariš novega.",
  "mcp.newKeyTitle": "Tvoj novi ključ",
  "mcp.showOnce": "Prekopiraj ga zdaj. BombVault hrani samo njegov prstni odtis in ga ne more pokazati znova.",
  "mcp.copyKey": "Kopiraj ključ",
  "mcp.dismissKey": "Prekopiral sem ga",
  "mcp.snippetsLabel": "Poveži odjemalca",
  "mcp.connectHint": "Izberi svojega odjemalca za nastavitev, narejeno zanj: ključ z njegovim imenom, konfiguracijo za kopiranje in korak s potrdilom, ki ga potrebuje. Vsak drug odjemalec se poveže prek Drug odjemalec. Kar pomočnik prebere, na primer imena elementov, zgodovino in sporočila o napakah, gre k ponudniku umetne inteligence za njim, potem ko BombVault odstrani poti gostitelja, lokacije repozitorijev in poverilnice.",
  "mcp.groupLocal": "Na tem računalniku",
  "mcp.groupCloud": "V oblaku",
  "mcp.cloudWarningTitle": "BombVault mora biti dosegljiv iz interneta",
  "mcp.cloudWarning": "Te storitve kličejo BombVault s strežnikov svojega ponudnika, ne s tvojega računalnika. BombVault mora biti takrat dosegljiv iz interneta z javno zaupanja vrednim potrdilom, na primer za povratnim posredniškim strežnikom. Prijava na tem strežniku lahko ščiti spletni vmesnik, a /mcp mora priti do BombVaulta, ki ključ preveri sam: te storitve se ne morejo prijaviti na posredniški strežnik. Le Chat zavrne samopodpisana potrdila.",
  "mcp.otherClient": "Drug odjemalec",
