  "mcp.setupChatGPT": "V ChatGPT odpri Nastavitve, Aplikacije in povezovalniki ter pod Napredne nastavitve vklopi način za razvijalce. Nato izberi Ustvari, poimenuj povezovalnik, prilepi URL povezovalnika kot URL strežnika MCP, izberi OAuth kot preverjanje pristnosti, potrdi, da mu zaupaš, in ga ustvari.",
  "mcp.setupClaudeAi": "Na claude.ai odpri Nastavitve, Povezovalniki in izberi Dodaj povezovalnik po meri. Poimenuj ga, prilepi URL povezovalnika, ID odjemalca in skrivnost OAuth pusti prazna ter ga dodaj. Nato izberi Poveži.",
  "mcp.copyConnector": "Kopiraj URL povezovalnika",
