  "mcp.noteGrok": "Dokumentacija za Grok ne prikaže njegovega obrazca za povezovalnike podrobno. Če ponuja samo prijavo in nobenega polja za glavo, ključa BombVault še ne more uporabiti.",
  "mcp.certNotForThisAddress": "Potrdilo BombVaulta ne navaja {host}, zato bodo pomočniki povezavo na ta naslov zavrnili. Dodaj naslov v potrdilo in ga nato prenesi za izseke.",
