  "api.title": "Žetoni API",
  "api.hint": "Žetoni za skripte, nadzorne plošče in domačo avtomatizacijo. Žeton odpre API pod /api/v1 in nič drugega. Obnovitve, brisanja in nastavitve ostanejo v tem spletnem vmesniku.",
